{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-cards.json
    The features as a grid of cards, tiles or bordered cells (the body of FeatureGrid). Icons are Lucide names.
    Props (p): features, cols, item. *}
{var $v_features = ($p['features'] ?? null)}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_item = ($p['item'] ?? 'card')}
{capture $c_15}
  {foreach og_l($v_features) as $v_feature}
    {if og_t(og_eq($v_item, 'tile'))}
      {capture $c_5}
        {capture $c_4}
          {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_feature, ['icon'])), 'size' => 20])|noescape}
          {capture $c_3}
            {capture $c_1}
              {=og_text(og_get($v_feature, ['title']))}
            {/capture}
            {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'base', 'weight' => 'bold', 'children' => (string) $c_1])|noescape}
            {capture $c_2}
              {=og_text(og_get($v_feature, ['text']))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_3])|noescape}
        {/capture}
        {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'start', 'children' => (string) $c_4])|noescape}
      {/capture}
      {=og_include('compose/Card.latte', ['variant' => 'compact', 'attrs' => og_attrs(['data-testid', 'feature-card']), 'children' => (string) $c_5])|noescape}
    {elseif og_t(og_eq($v_item, 'cell'))}
      {capture $c_9}
        {capture $c_6}
          {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_feature, ['icon'])), 'size' => 24])|noescape}
        {/capture}
        {=og_include('compose/IconBadge.latte', ['variant' => 'primary', 'size' => 'xl', 'attrs' => og_attrs(['data-testid', 'feature-icon']), 'children' => (string) $c_6])|noescape}
        {capture $c_7}
          {=og_text(og_get($v_feature, ['title']))}
        {/capture}
        {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'xl', 'weight' => 'semibold', 'class' => 'leading-6', 'children' => (string) $c_7])|noescape}
        {capture $c_8}
          {=og_text(og_get($v_feature, ['text']))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'class' => 'leading-5 text-muted-foreground', 'children' => (string) $c_8])|noescape}
      {/capture}
      {=og_include('compose/Stack.latte', ['gap' => '2', 'align' => 'center', 'class' => 'h-full gap-8 bg-background px-6 py-12 text-center', 'attrs' => og_attrs(['data-testid', 'feature-card']), 'children' => (string) $c_9])|noescape}
    {else}
      {capture $c_14}
        {capture $c_11}
          {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_feature, ['icon'])), 'size' => 24])|noescape}
          {capture $c_10}
            {=og_text(og_get($v_feature, ['title']))}
          {/capture}
          {=og_include('compose/CardTitle.latte', ['as' => 3, 'children' => (string) $c_10])|noescape}
        {/capture}
        {=og_include('compose/CardHeader.latte', ['class' => 'flex flex-col gap-4', 'children' => (string) $c_11])|noescape}
        {capture $c_13}
          {capture $c_12}
            {=og_text(og_get($v_feature, ['text']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_12])|noescape}
        {/capture}
        {=og_include('compose/CardContent.latte', ['children' => (string) $c_13])|noescape}
      {/capture}
      {=og_include('compose/Card.latte', ['variant' => 'default', 'attrs' => og_attrs(['data-testid', 'feature-card']), 'children' => (string) $c_14])|noescape}
    {/if}
  {/foreach}
{/capture}
{=og_include('compose/Grid.latte', ['cols' => og_s($v_cols), 'class' => og_s((og_t(og_eq($v_item, 'cell')) ? og_cnv(['w-full gap-px overflow-hidden bg-border p-px', og_preset('blocks/presets/defaults.json', ['features', 'cells'])]) : 'gap-6')), 'attrs' => og_attrs(['data-testid', 'feature-grid']), 'children' => (string) $c_15])|noescape}
